def seed_nctb_curriculum(force=False):
    """
    Seeds the initial NCTB 2026 Curriculum hierarchy:
    ClassLevel -> Subject -> Chapter -> Topic
    
    CRITICAL: Only runs when the database is empty (fresh database),
    or when explicitly forced (force=True).
    This ensures all user edits, updates, renamings, and deletions in
    "সিলেবাস ও পাঠ্যসূচি সেটিংস" are permanently preserved across server restarts.
    """
    if not force:
        try:
            if ClassLevel.query.first() is not None:
                return
        except Exception:
            pass

    for c_data in NCTB_2026_DATA:
        class_name = c_data["class_name"]
        code = c_data.get("code", "")
        order_num = c_data.get("order_num", 0)

        class_obj = ClassLevel.query.filter_by(name=class_name).first()
        if not class_obj:
            class_obj = ClassLevel(name=class_name, code=code, order_num=order_num)
            db.session.add(class_obj)
            db.session.flush()
        else:
            class_obj.code = code
            class_obj.order_num = order_num

        for s_data in c_data["subjects"]:
            sub_name = s_data["name"]
            sub_code = s_data.get("code", "")

            sub_obj = Subject.query.filter_by(class_id=class_obj.id, name=sub_name).first()
            if not sub_obj:
                sub_obj = Subject(class_id=class_obj.id, name=sub_name, code=sub_code)
                db.session.add(sub_obj)
                db.session.flush()
            else:
                sub_obj.code = sub_code

            for ch_data in s_data["chapters"]:
                ch_title = ch_data["title"]
                ch_no = ch_data.get("chapter_no", "")
                topics_list = ch_data.get("topics", [])

                ch_obj = Chapter.query.filter_by(subject_id=sub_obj.id, title=ch_title).first()
                if not ch_obj:
                    ch_obj = Chapter(subject_id=sub_obj.id, chapter_no=ch_no, title=ch_title)
                    db.session.add(ch_obj)
                    db.session.flush()
                else:
                    ch_obj.chapter_no = ch_no

                # Sync topics
                existing_topics = {t.title: t for t in Topic.query.filter_by(chapter_id=ch_obj.id).all()}
                
                for idx, t_title in enumerate(topics_list, 1):
                    if t_title not in existing_topics:
                        new_topic = Topic(chapter_id=ch_obj.id, title=t_title, order_num=idx)
                        db.session.add(new_topic)
                    else:
                        existing_topics[t_title].order_num = idx

    db.session.commit()
    print("[SUCCESS] NCTB 2026 Curriculum with Detailed Topics successfully synchronized into database!")
